{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": {
    "text": "Average flood depth, with and without NbS",
    "subtitle": "Land of the riverside tracts. Label: how much All NbS lowers it."
  },
  "width": 440,
  "height": 280,
  "transform": [
    {
      "calculate": "datum.scenario_name == 'No NbS' ? datum.mean_depth_m : 0",
      "as": "none_m"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "none_m",
          "as": "none_m"
        }
      ],
      "groupby": [
        "period"
      ]
    },
    {
      "calculate": "datum.none_m - datum.mean_depth_m",
      "as": "lowered_m"
    },
    {
      "calculate": "datum.scenario_name == 'All NbS' && datum.none_m > 0 ? '\u2212' + format(datum.lowered_m, '.2f') + ' m (\u2212' + format(datum.lowered_m / datum.none_m, '.0%') + ')' : ''",
      "as": "less"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar"
      },
      "encoding": {
        "x": {
          "field": "period",
          "type": "nominal",
          "title": null,
          "axis": {
            "labelAngle": 0
          }
        },
        "xOffset": {
          "field": "scenario_name",
          "type": "nominal",
          "sort": [
            "No NbS",
            "All NbS"
          ]
        },
        "y": {
          "field": "mean_depth_m",
          "type": "quantitative",
          "title": "Average flood depth (m)"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "title": "Scenario",
          "scale": {
            "domain": [
              "No NbS",
              "All NbS"
            ],
            "range": [
              "#e76f51",
              "#2a9d8f"
            ]
          }
        },
        "tooltip": [
          {
            "field": "period",
            "title": "Period"
          },
          {
            "field": "scenario_name",
            "title": "Scenario"
          },
          {
            "field": "mean_depth_m",
            "title": "Average depth (m)",
            "format": ".2f"
          },
          {
            "field": "lowered_m",
            "title": "Lower than No NbS (m)",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -7,
        "fontWeight": "bold",
        "fontSize": 11
      },
      "encoding": {
        "x": {
          "field": "period",
          "type": "nominal",
          "title": null,
          "axis": {
            "labelAngle": 0
          }
        },
        "xOffset": {
          "field": "scenario_name",
          "type": "nominal",
          "sort": [
            "No NbS",
            "All NbS"
          ]
        },
        "y": {
          "field": "mean_depth_m",
          "type": "quantitative",
          "title": "Average flood depth (m)"
        },
        "text": {
          "field": "less"
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['No NbS', 'All NbS'][datum.__input__]",
      "as": "scenario_name"
    },
    {
      "filter": "isValid(datum.svi) && isValid(datum.mean_depth_m)"
    },
    {
      "calculate": "replace(replace(datum.tract, /, (Scott|Rock Island|Henry) County.*$/, ''), 'Census Tract ', 'Tract ')",
      "as": "tract_short"
    }
  ],
  "title": {
    "text": "Social vulnerability against average flood depth",
    "subtitle": "Each riverside tract: its depth with No NbS and All NbS, joined."
  },
  "width": 520,
  "height": 320,
  "layer": [
    {
      "transform": [
        {
          "pivot": "scenario_name",
          "value": "mean_depth_m",
          "groupby": [
            "tract_fips",
            "tract_short",
            "svi"
          ]
        },
        {
          "calculate": "datum['No NbS'] - datum['All NbS']",
          "as": "lowered"
        }
      ],
      "params": [
        {
          "name": "hover",
          "select": {
            "type": "point",
            "fields": [
              "tract_fips"
            ],
            "on": "pointerover",
            "clear": "pointerout"
          }
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": 2
      },
      "encoding": {
        "x": {
          "field": "svi",
          "type": "quantitative",
          "title": "Social vulnerability (SVI percentile)",
          "scale": {
            "domain": [
              0,
              1
            ]
          }
        },
        "y": {
          "field": "No NbS",
          "type": "quantitative"
        },
        "y2": {
          "field": "All NbS"
        },
        "color": {
          "condition": {
            "param": "hover",
            "empty": false,
            "value": "#333"
          },
          "value": "#bbb"
        },
        "tooltip": [
          {
            "field": "tract_short",
            "title": "Tract"
          },
          {
            "field": "svi",
            "title": "SVI percentile",
            "format": ".2f"
          },
          {
            "field": "No NbS",
            "title": "Average depth, No NbS (m)",
            "format": ".2f"
          },
          {
            "field": "All NbS",
            "title": "Average depth, All NbS (m)",
            "format": ".2f"
          },
          {
            "field": "lowered",
            "title": "Lowered by NbS (m)",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 70,
        "opacity": 0.9,
        "stroke": "#fff",
        "strokeWidth": 0.5
      },
      "encoding": {
        "x": {
          "field": "svi",
          "type": "quantitative",
          "title": "Social vulnerability (SVI percentile)",
          "scale": {
            "domain": [
              0,
              1
            ]
          }
        },
        "y": {
          "field": "mean_depth_m",
          "type": "quantitative",
          "title": "Average flood depth over the tract's land (m)"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "title": "Scenario",
          "scale": {
            "domain": [
              "No NbS",
              "All NbS"
            ],
            "range": [
              "#e76f51",
              "#2a9d8f"
            ]
          }
        },
        "tooltip": [
          {
            "field": "tract_short",
            "title": "Tract"
          },
          {
            "field": "scenario_name",
            "title": "Scenario"
          },
          {
            "field": "svi",
            "title": "SVI percentile",
            "format": ".2f"
          },
          {
            "field": "mean_depth_m",
            "title": "Average depth (m)",
            "format": ".2f"
          }
        ]
      }
    }
  ]
}
